app.post('/webhook/zoho', (req, res) => {
  const body = req.body || {}; const ticket = body.ticket || body || {};
  const event = { type: body.event || 'ticket.updated', ticketNumber: ticket.ticketNumber || 'unknown', subject: ticket.subject || '', status: ticket.status || '', modifiedTime: ticket.modifiedTime || new Date().toISOString(), receivedAt: new Date().toISOString() };
  lastWebhookAt = event.receivedAt; webhookLog.unshift(event); webhookLog = webhookLog.slice(0,100); broadcast(event); res.status(200).json({ ok: true });
});
app.get('/api/webhook-log', (req, res) => res.json(webhookLog));
app.get('/webhook/stream', (req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive' });
  res.write('data: ' + JSON.stringify({ type: 'connected' }) + '\n\n'); sseClients.push(res); req.on('close', ()=>{ sseClients = sseClients.filter(c=>c!==res); });
});
